/// Emulate C++ std::stof / strtof prefix parsing.
/// Also reproduces libstdc++ std::stof's std::out_of_range throw (abort)
/// when strtof sets ERANGE: overflow to +-inf from a finite literal,
/// or underflow to a subnormal/zero result from a nonzero literal.
pub fn stof(s: &str) -> f32 {
    let s = s.trim_start_matches(|c: char| {
        matches!(c, ' ' | '\t' | '\n' | '\u{0b}' | '\u{0c}' | '\r')
    });
    // Longest prefix (on char boundaries) that Rust's f32 parser accepts.
    let mut end = s.len();
    while end > 0 {
        if s.is_char_boundary(end) {
            if let Ok(v) = s[..end].parse::<f32>() {
                check_erange(&s[..end], v);
                return v;
            }
        }
        end -= 1;
    }
    panic!("stof: no conversion could be performed");
}

fn check_erange(tok: &str, v: f32) {
    if v.is_infinite() {
        // Only an explicit inf/infinity literal escapes ERANGE.
        let t = tok.trim_start_matches(['+', '-']).to_ascii_lowercase();
        if !t.starts_with("inf") {
            panic!("stof: out_of_range");
        }
        return;
    }
    if v == 0.0 {
        // ERANGE if the literal's mantissa has any nonzero digit.
        if tok.bytes().any(|b| (b'1'..=b'9').contains(&b)) {
            panic!("stof: out_of_range");
        }
        return;
    }
    // Subnormal result => underflow => ERANGE.
    if v.abs() < f32::MIN_POSITIVE {
        panic!("stof: out_of_range");
    }
}

